bnr.css:
#ksBnr .seaw{position:relative;flex:none;width:390px;height:160px;overflow:hidden}
#ksBnr .seaw .bnr{position:absolute;left:0;top:0}
#ksBnr .seaw .sql{position:absolute;left:0px;width:780px;background-repeat:repeat-x;will-change:transform}
#ksBnr .seaw .sq1{top:0px;height:74px;background-image:url(ks_aea6cb8bfa4cdfac29231fc84afb9729.webp);background-size:390px 74px;animation:kbseaFlow 28s linear infinite}
#ksBnr .seaw .sq2{top:73px;height:52px;background-image:url(ks_901513e535a456c04a00e2f9d153404c.webp);background-size:390px 52px;animation:kbseaFlow 7s linear infinite}
#ksBnr .seaw .sq3{top:98px;height:62px;background-image:url(ks_3b7de0e548aa5814eee79b8bf01f08e8.webp);background-size:390px 62px;animation:kbseaFlow 2.3s linear infinite}
@keyframes kbseaFlow{from{transform:translateX(0)}to{transform:translateX(-390px)}}
#ksBnr .seaw .sqh{position:absolute;left:121px;top:23px;width:168px;height:120px;overflow:hidden}
#ksBnr .seaw .sqr{width:1680px;height:120px;background:url(ks_26493c0251b5e5e16213d1ed39f64a24.webp) 0 0/1680px 120px no-repeat;animation:kbseaRun 0.48s steps(10) infinite}
@keyframes kbseaRun{to{transform:translateX(-1680px)}}
@media (prefers-reduced-motion:reduce){#ksBnr .seaw .sql,#ksBnr .seaw .sqh{display:none}}
/* 設定の「演出を控えめにする」＝視差効果を減らすと同じ形（16.6） */
#ksBnr.calm .seaw .sql,#ksBnr.calm .seaw .sqh{display:none}

push.css:
.fxs .se{--pushA:#2EA0DC;--pushB:#0E5A9C;--pushC:#8FDDF7;--rim:#EAF8FF;--rimD:#0E3A66;
  --pushFace:radial-gradient(72% 40% at 50% 14%,rgba(255,255,255,.9),rgba(255,255,255,.3) 58%,rgba(255,255,255,0) 100%),linear-gradient(180deg,var(--pushC) 0%,var(--pushA) 40%,var(--pushB) 86%,#0A3766 100%)}
.fxs .push.se{box-shadow:inset 0 -9px 0 rgba(0,20,60,.18),inset 0 2px 0 rgba(255,255,255,.6),0 0 0 8px var(--rim),0 0 0 13px var(--rimD),0 10px 0 13px #0B2D52,0 22px 34px rgba(0,20,50,.5)}
.fxs .push.se span{text-shadow:0 3px 0 #0B3A6B,0 0 14px rgba(255,255,255,.55)}
.fxs .push.se::after{border-color:rgba(150,230,255,.95)}
.fxs .se .seab{position:absolute;left:-24px;top:-30px;width:248px;height:160px;pointer-events:none}
.fxs .se .seab svg{display:block;width:248px;height:160px;overflow:visible}
.fxs .se .sewv{animation:fxseWave 2.6s linear infinite}
@keyframes fxseWave{from{transform:translateX(0)}to{transform:translateX(-40px)}}
.fxs .se .sebb{opacity:0;animation:fxseBub 3s ease-in infinite}
@keyframes fxseBub{0%{opacity:0;transform:translateY(0)}15%{opacity:.95}100%{opacity:0;transform:translateY(-74px)}}
.fxs .se .sebu{transform-box:view-box;transform-origin:0 0;animation:fxseBuoy 2.6s ease-in-out infinite}
@keyframes fxseBuoy{0%,100%{transform:translate(197px,-14px) rotate(-6deg) translate(-197px,14px)}50%{transform:translate(197px,-14px) rotate(6deg) translate(-197px,14px)}}
.fxs .tap.se{color:#DFF6FF}
.fxs .pressed.se{box-shadow:0 0 0 8px var(--rim),0 0 0 13px var(--rimD),0 10px 0 13px #0B2D52}
.fxs .clips.se{position:absolute;z-index:4;left:50%;top:calc(50% - 40px);width:0;height:0}
.fxs .clips.se i{position:absolute;left:-5px;top:-5px;width:10px;height:10px;border-radius:50% 50% 50% 0;opacity:0;
  background:radial-gradient(circle at 38% 38%,#FFFFFF 0 22%,#B9EEFF 40%,#4FC3F7 100%);animation:fxseFly 1.05s cubic-bezier(.15,.7,.3,1) var(--d) both}
@keyframes fxseFly{0%{opacity:0;transform:translate(0,0) rotate(-45deg) scale(.4)}10%{opacity:1}55%{opacity:1;transform:translate(var(--x),var(--y)) rotate(-45deg) scale(var(--s))}
  100%{opacity:0;transform:translate(calc(var(--x) * 1.1),calc(var(--y) + 90px)) rotate(-45deg) scale(var(--s))}}
@media (prefers-reduced-motion:reduce){.fxs .se .sewv,.fxs .se .sebu{animation:none}
.fxs .se .sebb,.fxs .clips.se{display:none}}
/* 設定の「演出を控えめにする」＝視差効果を減らすと同じ形（16.6） */
.fxs.calm .se .sewv,.fxs.calm .se .sebu{animation:none}
.fxs.calm .se .sebb,.fxs.calm .clips.se{display:none}

